function LineChart({ dataset, title }) {
  if (!dataset) return null;
  if (dataset.error) return <Text variant="soft">{dataset.error}</Text>;
  return (
    <Col>
      <Text variant="label">{title}</Text>
      <Chart
        options={{
          data: dataset.rows,
          series: dataset.series.map((entry) => ({
            type: "line",
            xKey: "date",
            yKey: entry.key,
            yName: entry.label,
            marker: { enabled: false },
          })),
          legend: { enabled: false },
        }}
      />
    </Col>
  );
}

function Block({ data }) {
  return (
    <Grid columns={2} minColumnWidth={280}>
      <LineChart dataset={data.arr} title="ARR (12 x MRR), USD" />
      <LineChart dataset={data.cash} title="Cash balance, USD ($250k pre-seed in 2026-12, assumption)" />
    </Grid>
  );
}

